{
  "findings": [
    {
      "check_id": "CKV_AZURE_149",
      "title": "Ensure that Virtual machine does not enable password authentication",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "Password authentication is not explicitly disabled in this virtual machine scale set. This increases the risk of brute force attacks or unauthorized access."
    },
    {
      "check_id": "CKV_AZURE_151",
      "title": "Ensure Windows VM enables encryption",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "Disk encryption is not explicitly enabled for this Windows virtual machine scale set. This could lead to data exposure if the disks are compromised."
    }
  ],
  "patched_code": "resource "azurerm_windows_virtual_machine_scale_set" "negative4" {
  name                 = "negative4-vmss"
  resource_group_name  = azurerm_resource_group.negative4.name
  location             = azurerm_resource_group.negative4.location
  sku                  = "Standard_F2"
  computer_name_prefix = "vm-"

  encryption_at_host_enabled = true

  os_profile {
    admin_password = null
    admin_username = "adminuser"
    disable_password_authentication = true
  }

  os_profile_windows_config {
    enable_automatic_updates = true
    provision_vm_agent       = true
  }

  storage_profile_os_disk {
    name              = "osdisk"
    caching           = "ReadWrite"
    create_option     = "FromImage"
    managed_disk_type = "Standard_LRS"
    encryption_settings {
      enabled = true
    }
  }
}",
  "fix_summary": "Disabled password authentication and explicitly enabled disk encryption for the Windows virtual machine scale set."
}
